	push bc
	push de
	push hl
	ldh a, [hFishing_ROMBank]
	push af
	ldh a, [rSVBK]
	push af
	call Vector_UpdateSound
	pop af
	ldh [rSVBK], a
	pop af
	ldh [hFishing_ROMBank], a
	ld [$2000], a
	pop hl
	pop de
	pop bc
	pop af
	reti

; Fishing_STATScroll:
	push af
	ldh a, [rLY]
	cp $2a
	jr nz, @ +12 ; RAMCode_51_ccd1
	ldh a, [hFishing_Scroll + 1]
	ldh [rSCX], a
	ldh a, [hFishing_Scroll + 2]
	ldh [rSCY], a
	jr @ +11 ; RAMCode_51_ccda

; RAMCode_51_ccd1:
	cp $3f
	jr nz, @ +7 ; RAMCode_51_ccda
	xor a
	ldh [rSCX], a
	ldh [rSCY], a
; RAMCode_51_ccda:
	ldh a, [rLY]
	and $01
	nop
	nop
	pop af
	reti

; Fishing_SampleTimer:
	ld a, $ff
	ld [$2000], a
	ld a, [$4000]
	ldh [rNR50], a
	push hl
	ld hl, Fishing_SamplePos
	inc [hl]
	jr nz, @ +4 ; RAMCode_51_ccf5
	inc l
	inc [hl]
; RAMCode_51_ccf5:
	ldh a, [hFishing_ROMBank]
	ld [$2000], a
	pop hl
	pop af
	reti


